import { createPrompt, isEnterKey, makeTheme, useKeypress, usePrefix, useState } from '@inquirer/core'
import type { Prompt } from '@inquirer/type'

const MFA_CODE_PATTERN = /^\d{6}$/
const MASK_CHAR = '*'

type MfaCodePromptConfig = {
    message: string
    theme?: Parameters<typeof makeTheme>[0]
}

/**
 * Masked 6-digit code prompt that submits automatically the instant a valid code is typed —
 * no Enter needed. A TOTP code is single-use and expires in ~30s, so there's no benefit to
 * requiring a manual submit, and masking keeps it out of screen recordings/shoulder-surfing.
 */
export const promptMfaCode: Prompt<string, MfaCodePromptConfig> = createPrompt<string, MfaCodePromptConfig>(
    (config, done) => {
        const theme = makeTheme(config.theme)
        const [status, setStatus] = useState<'idle' | 'done'>('idle')
        const [errorMsg, setError] = useState<string | undefined>(undefined)
        const [value, setValue] = useState('')
        const prefix = usePrefix({ status, theme })

        useKeypress((key, rl) => {
            if (status !== 'idle') {
                return
            }

            if (isEnterKey(key)) {
                if (MFA_CODE_PATTERN.test(value)) {
                    setStatus('done')
                    done(value)
                } else {
                    rl.write(value)
                    setError('Enter a 6-digit code.')
                }
                return
            }

            const next = rl.line
            setValue(next)
            setError(undefined)

            if (MFA_CODE_PATTERN.test(next)) {
                setStatus('done')
                done(next)
                return
            }
        })

        const message = theme.style.message(config.message, status)
        const masked = MASK_CHAR.repeat(value.length)
        const formattedValue = status === 'done' ? theme.style.answer(masked) : masked
        const error = errorMsg ? theme.style.error(errorMsg) : ''

        return [[prefix, message, formattedValue].join(' '), error]
    }
)
